DROP TABLE IF EXISTS `view_encounter_diagnostico`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u257309594_salud`@`localhost` SQL SECURITY DEFINER VIEW `view_encounter_diagnostico`  AS SELECT `cc`.`id` AS `id`, `cc`.`encounter_id` AS `encounter_id`, `cc`.`code` AS `codigo`, NULL AS `tipo_diagnostico`, 'NO' AS `cronico`, NULL AS `root_id`, `cc`.`clinical_status` AS `condition_clinical_status`, `cc`.`verification_status` AS `condition_verification_status`, `cc`.`diagnosis_role` AS `tipo_prestacion`, NULL AS `objeto_prestacion`, `cc`.`subject_persona_id` AS `id_persona`, `enc`.`parent_id` AS `c_parent_id`, CASE `enc`.`parent_type` WHEN 'TURNO' THEN 'commonmodelsSchedulingTurno' WHEN 'DERIVACION' THEN 'commonmodelsClinicalEncounterReferralRequest' WHEN 'INTERNACION' THEN 'commonmodelsClinicalInpatientStay' WHEN 'GENERICO_AMB' THEN 'commonmodelsGenericoAMB' WHEN 'GENERICO_EMER' THEN 'commonmodelsGenericoEMER' WHEN 'GUARDIA' THEN 'commonmodelsClinicalEmergencyEmergencyEpisode' WHEN 'PASE_PREVIO' THEN 'commonmodelsOrganizationServiciosEfector' WHEN 'ENCUESTA_PARCHES' THEN 'commonmodelsClinicalEncuestaParchesMamarios' WHEN 'CIRUGIA' THEN 'commonmodelsSchedulingCirugia' ELSE NULL END AS `c_parent_class`, `enc`.`created_at` AS `c_created_at` FROM (`clinical_condition` `cc` join `encounter` `enc` on(`enc`.`id` = `cc`.`encounter_id` and `enc`.`deleted_at` is null)) WHERE `cc`.`deleted_at` is null AND (`cc`.`diagnosis_role` is null OR `cc`.`diagnosis_role` = '' OR `cc`.`diagnosis_role` in ('principal','secondary')) ;

